function Header() {
    try {
        const [isMenuOpen, setIsMenuOpen] = React.useState(false);
        const [currentRoute, setCurrentRoute] = React.useState(Router.currentRoute);

        React.useEffect(() => {
            const handleRouteChange = () => {
                setCurrentRoute(Router.currentRoute);
            };
            
            window.addEventListener('routechange', handleRouteChange);
            return () => window.removeEventListener('routechange', handleRouteChange);
        }, []);

        const scrollToSection = (sectionId) => {
            const element = document.getElementById(sectionId);
            if (element) {
                element.scrollIntoView({ behavior: 'smooth' });
                setIsMenuOpen(false);
            }
        };

        const navigateToHome = () => {
            scrollToSection('home');
            Router.navigate('/');
            setIsMenuOpen(false);
        };

        const getNavigationItems = () => {
            if (currentRoute === '/') {
                return [
                    { label: 'Home', action: () => scrollToSection('home') },
                    { label: 'Clients', action: () => scrollToSection('clients') },
                    { label: 'Services', action: () => scrollToSection('services') },
                    { label: 'About', action: () => scrollToSection('about') },
                    { label: 'Contact', action: () => scrollToSection('contact') }
                ];
            } else {
                return [
                    { label: 'Home', action: () => scrollToSection('home') },
                    { label: 'Projects', action: () => scrollToSection('projects') },
                    { label: 'Features', action: () => scrollToSection('features') },
                    { label: 'Contact', action: () => scrollToSection('contact') }
                ];
            }
        };

        const navItems = getNavigationItems();

        return (
            <header data-name="header" data-file="lib/components/Header.min.js" className="fixed top-0 w-full glass-header z-50">
                <nav className="container mx-auto px-4 py-4">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center logo-container">
                            <img 
                                src="asset/logos/infinity_logo.webp" 
                                alt="Infinity Squared Technologies Logo" 
                                className="w-20 cursor-pointer"
                                onClick={() => navigateToHome()}
                            />
                        </div>

                        <div className="hidden md:flex space-x-8">
                            {navItems.map((item, index) => (
                                <button 
                                    key={index}
                                    onClick={item.action} 
                                    className="text-gray-700 hover:text-black transition-colors font-medium cursor-pointer"
                                >
                                    {item.label}
                                </button>
                            ))}
                        </div>

                        <button 
                            className="md:hidden text-black"
                            onClick={() => setIsMenuOpen(!isMenuOpen)}
                        >
                            <i className={`fas ${isMenuOpen ? 'fa-times' : 'fa-bars'} text-xl`}></i>
                        </button>
                    </div>

                    <div
                        className={`md:hidden fixed left-0 right-0 top-[72px] z-40 glass-mobile-menu transition-all duration-300 ease-in-out overflow-hidden ${isMenuOpen ? 'max-h-96 opacity-100 scale-100' : 'max-h-0 opacity-0 scale-95 pointer-events-none'}`}
                        style={{ willChange: 'max-height, opacity, transform' }}
                        aria-hidden={!isMenuOpen}
                    >
                        <div className="flex flex-col space-y-3 px-4 py-4">
                            {navItems.map((item, index) => (
                                <button 
                                    key={index}
                                    onClick={item.action} 
                                    className="text-gray-700 hover:text-black py-2 text-left cursor-pointer"
                                >
                                    {item.label}
                                </button>
                            ))}
                        </div>
                    </div>
                </nav>
            </header>
        );
    } catch (error) {
        console.error('Header component error:', error);
        reportError(error);
        return (
            <header className="fixed top-0 w-full glass-header z-50">
                <nav className="container mx-auto px-4 py-4">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center logo-container">
                            <img 
                                src="asset/logos/infinity_logo.webp" 
                                alt="Infinity Squared Technologies Logo" 
                                className="w-20"
                            />
                        </div>
                        <p className="text-gray-500">Unable to load header section</p>
                    </div>
                </nav>
            </header>
        );
    }
}
